{
  "title": "English Practice: Gerunds & Vocab",
  "q": [
    {
      "t": "Match 'diligent' with its meaning.",
      "type": "match",
      "opts": ["lazy", "hardworking", "angry", "quiet"],
      "ans": "hardworking"
    },
    {
      "t": "Fill in the blank: She enjoys _______ classical music.",
      "type": "blank",
      "opts": [],
      "ans": "listening to"
    },
    {
      "t": "Complete: He studied hard _______ he could pass the exam.",
      "type": "open",
      "opts": [],
      "ans": "so that"
    }
  ]
}
